mapper.select:
SELECT COUNT(*)
FROM   PURCHASE_ORDER P LEFT JOIN CLIENT C ON P.CLIENT_NO = C.CLIENT_NO AND C.DEL_STATUS = 0 
						 LEFT JOIN EMP E ON P.EMP_NO = E.EMP_NO AND E.DEL_STATUS = 0


P.DEL_STATUS = 0

AND C.CLIENT_NAME LIKE '%' || #{client_Name} || '%'


AND E.EMP_NAME LIKE '%' || #{empName} || '%'


AND P.IN_STATUS = #{in_Status}


AND P.PURCHASE_DATE >= #{purchase_Date_Start}


AND P.PURCHASE_DATE <= #{purchase_Date_End}

SELECT P.PURCHASE_NO, P.PURCHASE_DATE, P.IN_STATUS, P.DEL_STATUS, P.COMPLETE_DATE, P.IN_DATE , C.CLIENT_NO, C.CLIENT_NAME, E.EMP_NO, E.EMP_NAME , I.PARTS_NO, I.PURCHASE_ITEM_CNT, I.PURCHASE_ITEM_INCNT, I.PURCHASE_ITEM_COST , PA.PARTS_NAME FROM (SELECT ROWNUM RN, A.* FROM (SELECT * FROM PURCHASE_ORDER WHERE DEL_STATUS = 0 ORDER BY PURCHASE_NO DESC ) A )P LEFT JOIN CLIENT C ON P.CLIENT_NO = C.CLIENT_NO LEFT JOIN EMP E ON P.EMP_NO = E.EMP_NO LEFT JOIN PURCHASE_ITEM I ON P.PURCHASE_NO = I.PURCHASE_NO LEFT JOIN PARTS PA ON I.PARTS_NO = PA.PARTS_NO
AND C.CLIENT_NAME LIKE '%' || #{client_Name} || '%'
AND E.EMP_NAME LIKE '%' || #{empName} || '%'
AND P.IN_STATUS = #{in_Status}
AND P.PURCHASE_DATE >= #{purchase_Date_Start}
AND P.PURCHASE_DATE <= #{purchase_Date_End}
RN >= 1 AND RN <= 10
ORDER BY P.PURCHASE_NO DESC
